export const RULES_EN: [RegExp, (m: RegExpMatchArray) => string][] = [
  [/^Gói có (\d+) skill\. Hãy chọn skill muốn thêm\.$/, (m) => `This package has ${m[1]} skills. Choose which to add.`],
  [/^Bỏ qua (\d+) file có định dạng không hỗ trợ: (.+)$/, (m) => `Skipped ${m[1]} unsupported files: ${m[2]}`],
  [/^Đã thêm (\d+) skill$/, (m) => `Added ${m[1]} skills`],
  [/^Đã khôi phục (.+) về v(\d+)$/, (m) => `Restored ${m[1]} to v${m[2]}`],
  [/^Đã bật (.+) trong dự án$/, (m) => `Turned on ${m[1]} for this project`],
  [/^Đã tắt (.+) trong dự án$/, (m) => `Turned off ${m[1]} for this project`],
  [/^Bật (.+) trong dự án$/, (m) => `Turn on ${m[1]} for this project`],
  [/^Quản trị viên chưa cho phép tài khoản của bạn dùng model (.+)\.$/, (m) => `The administrator hasn't allowed your account to use the ${m[1]} model.`],
  [/^Đăng nhập bằng (Google|GitHub|Apple) chưa được cấu hình trên máy chủ\.$/, (m) => `${m[1]} sign-in isn't set up on the server yet.`],
  [/^Đang chuyển (.+)… \(tệp quét sẽ qua OCR, có thể mất ~1 phút\)$/, (m) => `Converting ${m[1]}… (scans go through OCR, may take ~1 min)`],
  [/^Lỗi — (.+)$/, (m) => `Error — ${m[1]}`],
  [/^"(.+)" vượt quá giới hạn (\d+)MB$/, (m) => `"${m[1]}" exceeds the ${m[2]}MB limit`],
  [/^Không tải được "(.+)" lên server$/, (m) => `Could not upload "${m[1]}" to the server`],
  [/^Tối đa (\d+) tệp mỗi tin nhắn$/, (m) => `At most ${m[1]} files per message`],
  [/^"(.+)" là tệp nhị phân \((.+)\) mà Synchro chưa đọc được\.$/, (m) => `"${m[1]}" is a binary file (${m[2]}) that Synchro cannot read yet.`],
  [/^Chào buổi sáng(?:, (.+))?$/, (m) => "Good morning" + (m[1] ? ", " + m[1] : "")],
  [/^Chào buổi trưa(?:, (.+))?$/, (m) => "Good midday" + (m[1] ? ", " + m[1] : "")],
  [/^Chiều tốt lành(?:, (.+))?$/, (m) => "Good afternoon" + (m[1] ? ", " + m[1] : "")],
  [/^([\d.,]+) ký tự$/, (m) => `${m[1]} chars`],
  [/^Không đọc được nội dung văn bản từ "(.+)"$/, (m) => `Couldn't read text from "${m[1]}"`],
  [/^Đã dùng (\d+)% dung lượng dự án$/, (m) => `${m[1]}% of project capacity used`],
  [/^Đã chọn (\d+)$/, (m) => `${m[1]} selected`],
  [/^Xóa (\d+) mục đã chọn$/, (m) => `Delete ${m[1]} selected`],
  [/^Cập nhật (.+)$/, (m) => "Updated " + m[1]],
  [/^(\d+) giờ trước$/, (m) => `${m[1]}h ago`],
  [/^(\d+) ngày trước$/, (m) => `${m[1]}d ago`],
  [/^Xem dự án đã lưu trữ \((\d+)\)$/, (m) => `View archived projects (${m[1]})`],
  [/^(\d+) phút trước$/, (m) => `${m[1]} min ago`],
  [/^Đã thêm (\d+) tệp$/, (m) => `Added ${m[1]} file${m[1] === "1" ? "" : "s"}`],
  [/^Đã thêm vào "(.+)"$/, (m) => `Added to "${m[1]}"`],
  [/^Đã chọn micro: (.+)$/, (m) => `Microphone selected: ${m[1]}`],
  [/^Đã kết nối (.+)$/, (m) => `Connected ${m[1]}`],
  [/^Đã ngắt kết nối (.+)$/, (m) => `Disconnected ${m[1]}`],
  [/^Đã gỡ (.+)$/, (m) => `Removed ${m[1]}`],
  [/^Đã tải lên (.+)$/, (m) => `Uploaded ${m[1]}`],
  [/^Đã thêm (.+)$/, (m) => `Added ${m[1]}`],
  [/^(.+) đã được cài đặt$/, (m) => `${m[1]} installed`],
  [/^Xóa (tài liệu|bản trình bày|thiết kế)$/, (m) => `Delete ${({ "tài liệu": "document", "bản trình bày": "presentation", "thiết kế": "design" } as Record<string, string>)[m[1]]}`],
  [/^Bạn đã dùng Synchro một lúc rồi — nghỉ giải lao (\d+(?:\.\d+)?) (giờ|phút) nhé$/, (m) => `You've been using Synchro for a while — take a ${m[1]} ${m[2] === "giờ" ? "hour" : "minute"} break`],
  [/^Hãy thử kỹ năng "(.+)" với một ví dụ nhỏ\.$/, (m) => `Try the "${m[1]}" skill on a small example.`],
  [/^Hãy thử plugin "(.+)" giúp tôi\.$/, (m) => `Try the "${m[1]}" plugin for me.`],
  [/^Hãy giúp tôi tạo một (.+) mới\.$/, (m) => `Help me create a new ${m[1]}.`],
  [/^Hướng dẫn tôi tạo một (.+) từ đầu\.$/, (m) => `Walk me through creating a ${m[1]} from scratch.`],
  [/^(\d+) (giờ|phút)$/, (m) => `${m[1]} ${m[2] === "giờ" ? "hr" : "min"}`],
  [/^Đã áp dụng hướng dẫn của bạn: (.+)$/, (m) => `Applied your instructions: ${m[1]}`],
];

